import{_ as e}from"./chunks/neuhrazena_faktura.DeR0vfSm.js";import{_ as t,o,c as n,aa as i}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/academy/img/orientace/03.webp",b=JSON.parse('{"title":"Orientace v aplikaci","description":"","frontmatter":{"title":"Orientace v aplikaci","wiki":"cs:firstofall:description"},"headers":[],"relativePath":"firstofall/description.md","filePath":"firstofall/description.md","lastUpdated":1794209661000}'),s={name:"firstofall/description.md"};function l(p,a,v,d,u,k){return o(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="orientace-v-aplikaci" tabindex="-1">Orientace v aplikaci <a class="header-anchor" href="#orientace-v-aplikaci" aria-label="Permalink to &quot;Orientace v aplikaci&quot;">​</a></h1><p>Obrazovka Buildary má tři části: <strong>horní lištu</strong>, <strong>levý panel</strong> se stavbou a jejími moduly a <strong>hlavní okno</strong>, ve kterém pracujete. Tady najdete, co je kde.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/orientace">Zorientovat se v aplikaci</a> v Akademii.</p><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Buildary s otevřenou stavbou: horní lišta, levý panel s moduly a hlavní okno s deníkem" loading="lazy"><figcaption>Otevřená stavba: vlevo panel s moduly, nahoře lišta, uprostřed hlavní okno.</figcaption></figure><h2 id="horni-lista" tabindex="-1">Horní lišta <a class="header-anchor" href="#horni-lista" aria-label="Permalink to &quot;Horní lišta&quot;">​</a></h2><p>Vpravo v horní liště jsou tři ikony:</p><ul><li><strong>Otazník</strong> – otevře tuto nápovědu.</li><li><strong>Zvoneček</strong> – notifikace: nové úkoly a jejich změny, nepodepsané záznamy nebo potíže s elektronickým podpisem.</li><li><strong>Postava</strong> (nebo vaše profilová fotka) – uživatelské menu s položkami <strong>Novinky a změny v aplikaci</strong>, <strong>Nastavení podpisu</strong> a <strong>Odhlásit</strong>. Kliknutím na své jméno otevřete <a href="/buildary-help-preview/firstofall/account">správu účtu</a>.</li></ul><p>Vedle ikon se občas zobrazí barevné upozornění, například na školení nebo novou verzi mobilní aplikace.</p><h2 id="levy-panel" tabindex="-1">Levý panel <a class="header-anchor" href="#levy-panel" aria-label="Permalink to &quot;Levý panel&quot;">​</a></h2><p>Nahoře je obrázek a název stavby, na které právě jste. Kliknutím na obrázek nebo název otevřete nastavení stavby.</p><p>Pod názvem je doména, do které stavba patří, a tři ikony:</p><table tabindex="0"><thead><tr><th>Ikona</th><th>Co otevře</th></tr></thead><tbody><tr><td>Seznam</td><td><strong>Seznam staveb</strong> – všechny stavby, ke kterým máte přístup. Odtud přejdete na jinou stavbu nebo založíte novou.</td></tr><tr><td>Ozubené kolo</td><td><strong>Nastavení stavby</strong> – údaje o stavbě, zapnuté moduly, projektový tým, výkresy a číselníky.</td></tr><tr><td>Glóbus</td><td><strong>Seznam domén</strong> – vaše domény, jejich uživatelé a <a href="/buildary-help-preview/firstofall/payment">fakturace</a>.</td></tr></tbody></table><p>Pod ikonami jsou moduly stavby a jejich stránky. Zobrazují se jen moduly, které jsou na stavbě zapnuté, takže hned vidíte, kde můžete pracovat. Modul sbalíte nebo rozbalíte kliknutím na jeho název.</p><h2 id="seznam-staveb" tabindex="-1">Seznam staveb <a class="header-anchor" href="#seznam-staveb" aria-label="Permalink to &quot;Seznam staveb&quot;">​</a></h2><p>Po přihlášení si v Seznamu staveb vyberte stavbu – kliknutím na název ji otevřete. Otevře se poslední deník, se kterým jste pracovali.</p><ul><li>Ikonou tužky na konci řádku upravíte údaje o stavbě.</li><li>Je-li seznam prázdný, nejdřív <a href="/buildary-help-preview/diary/projectsetup">založte stavbu</a> nebo počkejte, až vás někdo na stavbu přizve.</li><li>Aby šlo pracovat s úkoly nebo soupisy, musí mít stavba zapnutý příslušný modul.</li></ul><div class="warning custom-block"><p class="custom-block-title">Oranžová nebo červená ikona u stavby</p><p>Ikona <img src="'+e+'" alt="neuhrazená faktura" width="24" data-no-zoom loading="lazy"> v Seznamu staveb znamená problém s úhradou faktur. Podrobnosti najdete v doméně stavby (ikona glóbu) – viz <a href="/buildary-help-preview/firstofall/payment#splatnost-a-neuhrazene-faktury">Placený režim a fakturace</a>.</p></div>',17)])])}const h=t(s,[["render",l]]);export{b as __pageData,h as default};
